UPDATE sys_flow_user_group
SET group_name = #{group.groupName},
    status = #{group.status},
    remark = #{group.remark},
    update_by = #{group.updateBy},
    update_time = #{group.updateTime}
WHERE id = #{group.id}
  AND tenant_id = #{tenantId}
  AND del_flag = 0

UPDATE sys_flow_user_group_member
SET del_flag = id,
    update_time = CURRENT_TIMESTAMP
WHERE group_id = #{groupId}
  AND tenant_id = #{tenantId}
  AND del_flag = 0

